#!/usr/bin/env python3
import base64
import gzip
import hashlib
import pathlib
import sys

root = pathlib.Path(sys.argv[1]).resolve()
if not (root / "go.mod").is_file():
    raise SystemExit("target is not a HYZoraX source tree")

protocol = root / "internal/helper/protocol.go"
if "const ProtocolVersion = 21" not in protocol.read_text():
    raise SystemExit("Protocol V21 invariant failed")

index = gzip.decompress(base64.b64decode(""))
css = gzip.decompress(base64.b64decode(""))

expected = {
    "internal/web/static/index.html": ("b70b0863ed1070cccfc918d5d918af3cdb25903f1c3d515271c3abfb9a7ce1ba", index),
    "internal/web/static/app.css": ("b6d6e86e2cb372a676ce97cf98cbb6610ccb2fd0ae47a17d42cdd2c71d723e04", css),
}
for rel, (digest, data) in expected.items():
    if hashlib.sha256(data).hexdigest() != digest:
        raise SystemExit(f"embedded payload checksum mismatch: {rel}")
    (root / rel).write_bytes(data)

replacements = {
    "internal/web/assets_test.go": [
        ("Version 1.7.9", "Version 1.8.0"),
        ("release version 1.7.9", "release version 1.8.0"),
    ],
    "internal/httpapi/app_test.go": [
        ("Version 1.7.9", "Version 1.8.0"),
    ],
}
for rel, pairs in replacements.items():
    path = root / rel
    text = path.read_text()
    for old, new in pairs:
        if old not in text:
            raise SystemExit(f"expected V1.7.9 marker missing: {rel}: {old}")
        text = text.replace(old, new)
    path.write_text(text)

if "Version 1.8.0" not in (root / "internal/web/static/index.html").read_text():
    raise SystemExit("V1.8.0 footer invariant failed")
if "Desktop management console" not in (root / "internal/web/static/app.css").read_text():
    raise SystemExit("software UI invariant failed")

print("V1.8.0 software UI patch applied")

